package mekanism.common.lib.security;

import java.util.Objects;
import java.util.UUID;
import java.util.function.Function;
import java.util.function.Supplier;
import mekanism.api.security.IOwnerObject;
import mekanism.api.security.ISecurityObject;
import mekanism.api.security.ISecurityUtils;
import mekanism.api.security.SecurityMode;
import mekanism.api.text.EnumColor;
import mekanism.client.MekanismClient;
import mekanism.common.MekanismLang;
import mekanism.common.base.MekanismPermissions;
import mekanism.common.config.MekanismConfig;
import mekanism.common.lib.frequency.FrequencyTypes;
import mekanism.common.util.MekanismUtils;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.player.Player;
import net.neoforged.neoforge.server.permission.PermissionAPI;
import net.neoforged.neoforge.transfer.transaction.TransactionContext;
import org.jspecify.annotations.Nullable;

/// @apiNote Do not instantiate this class directly as it will be done via the service loader. Instead, access instances of this via [ISecurityUtils#INSTANCE]
public final class SecurityUtils implements ISecurityUtils {

    public static SecurityUtils get() {
        return (SecurityUtils) INSTANCE;
    }

    /// Whether ops can bypass security and a given player is considered an Op.
    ///
    /// @param p player to check
    ///
    /// @return if the player has operator privileges
    private boolean isOp(Player p) {
        Objects.requireNonNull(p, "Player may not be null.");
        return MekanismConfig.general.opsBypassRestrictions.get() && p instanceof ServerPlayer player &&
               PermissionAPI.getPermission(player, MekanismPermissions.BYPASS_SECURITY);
    }

    @Override
    public boolean canAccess(Player player, Supplier<@Nullable ISecurityObject> securityProvider, Supplier<@Nullable IOwnerObject> ownerProvider) {
        //If the player is an op allow bypassing any restrictions
        return isOp(player) || canAccess(player.getUUID(), securityProvider, ownerProvider, player.level().isClientSide());
    }

    @Override
    public <PROVIDER> boolean canAccess(Player player, PROVIDER provider, Function<PROVIDER, @Nullable ISecurityObject> securityProvider, Function<PROVIDER, @Nullable IOwnerObject> ownerProvider) {
        return isOp(player) || canAccess(player.getUUID(), provider, securityProvider, ownerProvider, player.level().isClientSide());
    }

    @Override
    public boolean canAccess(@Nullable UUID player, Supplier<@Nullable ISecurityObject> securityProvider, Supplier<@Nullable IOwnerObject> ownerProvider, boolean isClient) {
        if (!MekanismConfig.general.allowProtection.get()) {
            //If protection is disabled, access is always granted
            return true;
        }
        //Note: We don't just use getSecurityObject here as we support checking access to things that are only owned and don't have security
        ISecurityObject securityCapability = securityProvider.get();
        if (securityCapability == null) {
            //If it is an owner item but not a security item make sure the owner matches
            IOwnerObject ownerCapability = ownerProvider.get();
            if (ownerCapability != null) {
                //If it is an owner object but not a security object make sure the owner matches
                UUID owner = ownerCapability.getOwnerUUID();
                return owner == null || owner.equals(player);
            }
            //Otherwise, if there is no owner AND no security, access is always granted
            return true;
        }
        return canAccessObject(player, securityCapability, isClient);
    }

    @Override
    public <PROVIDER> boolean canAccess(@Nullable UUID player, PROVIDER provider, Function<PROVIDER, @Nullable ISecurityObject> securityProvider,
          Function<PROVIDER, @Nullable IOwnerObject> ownerProvider, boolean isClient) {
        if (!MekanismConfig.general.allowProtection.get()) {
            //If protection is disabled, access is always granted
            return true;
        }
        //Note: We don't just use getSecurityObject here as we support checking access to things that are only owned and don't have security
        ISecurityObject securityCapability = securityProvider.apply(provider);
        if (securityCapability == null) {
            //If it is an owner item but not a security item make sure the owner matches
            IOwnerObject ownerCapability = ownerProvider.apply(provider);
            if (ownerCapability != null) {
                //If it is an owner object but not a security object make sure the owner matches
                UUID owner = ownerCapability.getOwnerUUID();
                return owner == null || owner.equals(player);
            }
            //Otherwise, if there is no owner AND no security, access is always granted
            return true;
        }
        return canAccessObject(player, securityCapability, isClient);
    }

    @Override
    public boolean canAccessObject(Player player, ISecurityObject security) {
        //If the player is an op allow bypassing any restrictions
        return isOp(player) || canAccessObject(player.getUUID(), security, player.level().isClientSide());
    }

    @Override
    public boolean canAccessObject(@Nullable UUID player, ISecurityObject security, boolean isClient) {
        Objects.requireNonNull(security, "Security object may not be null.");
        if (!MekanismConfig.general.allowProtection.get()) {
            //If protection is disabled, access is always granted
            return true;
        }
        UUID owner = security.getOwnerUUID();
        if (owner == null || owner.equals(player)) {
            return true;
        }
        return switch (getEffectiveSecurityMode(security, isClient)) {
            case PUBLIC -> true;
            case PRIVATE -> false;
            case TRUSTED -> {
                if (player == null) {
                    yield false;
                } else if (isClient) {
                    //If we are the client, then we just return true and assume that we can access the frequency
                    // as we don't know which players are set as trusted
                    //TODO: Technically in single player if the player is the single player owner we could hackily reach across
                    // sides but I don't think there is much benefit to doing so for how complex it is to do
                    yield true;
                }
                SecurityFrequency frequency = FrequencyTypes.SECURITY.getFrequency(null, SecurityMode.PUBLIC, owner);
                //If we have no frequency handle it as if it was private, otherwise check if the player is trusted
                yield frequency != null && frequency.isTrusted(player);
            }
        };
    }

    @Override
    public boolean moreRestrictive(SecurityMode base, SecurityMode overridden) {
        Objects.requireNonNull(base, "Base security mode may not be null.");
        Objects.requireNonNull(base, "Override security mode may not be null.");
        return switch (overridden) {
            //If the override mode is public it is never more restrictive than the normal level
            case PUBLIC -> false;
            //If the override mode is private it is only more restrictive if the base isn't already private
            case PRIVATE -> base != SecurityMode.PRIVATE;
            //If the override mode is trusted it is only more restrictive if the normal level was public
            case TRUSTED -> base == SecurityMode.PUBLIC;
        };
    }

    public SecurityData getFinalData(ISecurityObject securityObject, boolean isClient) {
        if (!MekanismConfig.general.allowProtection.get()) {
            return SecurityData.DUMMY;
        }
        SecurityData data = getData(securityObject.getOwnerUUID(), isClient);
        SecurityMode mode = securityObject.getSecurityMode();
        if (data.override() && moreRestrictive(mode, data.mode())) {
            //If our frequency's data is set to override, and it is more restrictive than the current mode,
            // return the data for our frequency
            return data;
        }
        return new SecurityData(mode, false);
    }

    public SecurityData getData(@Nullable UUID uuid, boolean isClient) {
        if (uuid == null) {
            return SecurityData.DUMMY;
        } else if (isClient) {
            return MekanismClient.clientSecurityMap.getOrDefault(uuid, SecurityData.DUMMY);
        }
        SecurityFrequency frequency = FrequencyTypes.SECURITY.getFrequency(null, SecurityMode.PUBLIC, uuid);
        return frequency == null ? SecurityData.DUMMY : new SecurityData(frequency);
    }

    @Override
    public SecurityMode getSecurityMode(Supplier<@Nullable ISecurityObject> securityProvider, Supplier<@Nullable IOwnerObject> ownerProvider, boolean isClient) {
        if (!MekanismConfig.general.allowProtection.get()) {
            return SecurityMode.PUBLIC;
        }
        ISecurityObject security = securityProvider.get();
        if (security != null) {
            return getEffectiveSecurityMode(security, isClient);
        }
        IOwnerObject ownerObject = ownerProvider.get();
        return ownerObject == null ? SecurityMode.PUBLIC : SecurityMode.PRIVATE;
    }

    @Override
    public <PROVIDER> SecurityMode getSecurityMode(PROVIDER provider, Function<PROVIDER, @Nullable ISecurityObject> securityProvider,
          Function<PROVIDER, @Nullable IOwnerObject> ownerProvider, boolean isClient) {
        if (!MekanismConfig.general.allowProtection.get()) {
            return SecurityMode.PUBLIC;
        }
        ISecurityObject security = securityProvider.apply(provider);
        if (security != null) {
            return getEffectiveSecurityMode(security, isClient);
        }
        IOwnerObject ownerObject = ownerProvider.apply(provider);
        return ownerObject == null ? SecurityMode.PUBLIC : SecurityMode.PRIVATE;
    }

    @Override
    public SecurityMode getEffectiveSecurityMode(ISecurityObject securityObject, boolean isClient) {
        Objects.requireNonNull(securityObject, "Security object may not be null.");
        return getFinalData(securityObject, isClient).mode();
    }

    public void incrementSecurityMode(Player player, @Nullable ISecurityObject security, @Nullable TransactionContext transaction) {
        if (security != null && security.ownerMatches(player)) {
            security.setSecurityMode(security.getSecurityMode().getNext(), transaction);
        }
    }

    public void decrementSecurityMode(Player player, @Nullable ISecurityObject security, @Nullable TransactionContext transaction) {
        if (security != null && security.ownerMatches(player)) {
            security.setSecurityMode(security.getSecurityMode().getPrevious(), transaction);
        }
    }

    @Override
    public void displayNoAccess(Player player) {
        Objects.requireNonNull(player, "Player may not be null.");
        player.sendSystemMessage(MekanismUtils.logFormat(EnumColor.RED, MekanismLang.NO_ACCESS));
    }

    public boolean isTrusted(SecurityMode mode, @Nullable UUID ownerUUID, UUID playerUUID) {
        if (ownerUUID != null && mode == SecurityMode.TRUSTED) {
            SecurityFrequency frequency = FrequencyTypes.SECURITY.getFrequency(null, SecurityMode.PUBLIC, ownerUUID);
            return frequency != null && frequency.isTrusted(playerUUID);
        }
        return false;
    }
}

package mekanism.common.tile;

import java.util.Optional;
import java.util.UUID;
import mekanism.api.IContentsListener;
import mekanism.api.inventory.IInventorySlot;
import mekanism.api.security.ISecurityUtils;
import mekanism.api.security.SecurityMode;
import mekanism.common.capabilities.holder.container.IContainerHolder;
import mekanism.common.capabilities.holder.container.MekContainerHelper;
import mekanism.common.inventory.container.ISecurityContainer;
import mekanism.common.inventory.slot.SecurityInventorySlot;
import mekanism.common.lib.frequency.FrequencyTypes;
import mekanism.common.lib.security.SecurityFrequency;
import mekanism.common.network.to_client.security.PacketSyncSecurity;
import mekanism.common.registries.MekanismBlocks;
import mekanism.common.tile.base.TileEntityMekanism;
import mekanism.common.tile.interfaces.IBoundingBlock;
import net.minecraft.core.BlockPos;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.server.players.NameAndId;
import net.minecraft.server.players.UserNameToIdResolver;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.block.state.BlockState;
import net.neoforged.neoforge.network.PacketDistributor;
import org.jetbrains.annotations.UnknownNullability;
import org.jspecify.annotations.Nullable;

public class TileEntitySecurityDesk extends TileEntityMekanism implements IBoundingBlock {

    @UnknownNullability//Initialized via getInitialInventory
    private SecurityInventorySlot unlockSlot;
    @UnknownNullability//Initialized via getInitialInventory
    private SecurityInventorySlot lockSlot;

    public TileEntitySecurityDesk(BlockPos pos, BlockState state) {
        super(MekanismBlocks.SECURITY_DESK, pos, state);
    }

    @Override
    protected IContainerHolder<IInventorySlot> getInitialInventory(IContentsListener listener) {
        MekContainerHelper<IInventorySlot> builder = MekContainerHelper.forSide(facingSupplier);
        builder.addContainer(unlockSlot = SecurityInventorySlot.unlock(this::getOwnerUUID, listener, 146, 18));
        builder.addContainer(lockSlot = SecurityInventorySlot.lock(listener, 146, 97));
        return builder.build();
    }

    @Override
    protected boolean onUpdateServer(ServerLevel level) {
        boolean sendUpdatePacket = super.onUpdateServer(level);
        SecurityFrequency frequency = getFreq();
        UUID ownerUUID = getOwnerUUID();
        if (ownerUUID != null && frequency != null) {
            unlockSlot.unlock(ownerUUID, null);
            lockSlot.lock(ownerUUID, frequency, null);
        }
        return sendUpdatePacket;
    }

    /// Only call on the server side
    public void toggleOverride() {
        SecurityFrequency frequency = getFreq();
        if (frequency != null) {
            frequency.setOverridden(!frequency.isOverridden());
            markForSave();
            // send the security update to other players; this change will be visible on machine security tabs
            PacketDistributor.sendToAllPlayers(new PacketSyncSecurity(frequency));
            validateAccess();
        }
    }

    /// Validates access for anyone who might be accessing a GUI that changed security modes
    private void validateAccess() {
        if (level != null) {
            MinecraftServer server = level.getServer();
            if (server != null) {
                for (ServerPlayer player : server.getPlayerList().getPlayers()) {
                    closeIfNoAccess(player);
                }
            }
        }
    }

    public void removeTrusted(int index) {
        SecurityFrequency frequency = getFreq();
        if (frequency != null) {
            UUID removed = frequency.removeTrusted(index);
            markForSave();
            if (removed != null && level != null) {
                MinecraftServer server = level.getServer();
                if (server != null) {
                    closeIfNoAccess(server.getPlayerList().getPlayer(removed));
                }
            }
        }
    }

    private void closeIfNoAccess(@Nullable Player player) {
        if (player != null && player.containerMenu instanceof ISecurityContainer container && !container.canPlayerAccess(player)) {
            //Boot any players out of the container if they no longer have access to viewing it
            player.closeContainer();
        }
    }

    public void setSecurityDeskMode(SecurityMode mode) {
        SecurityFrequency frequency = getFreq();
        if (frequency != null) {
            SecurityMode old = frequency.getSecurity();
            if (old != mode) {
                //TODO - 1.20.4: Is this fine, or do we need to make security frequencies override the identity
                frequency.setSecurityMode(mode);
                markForSave();
                // send the security update to other players; this change will be visible on machine security tabs
                PacketDistributor.sendToAllPlayers(new PacketSyncSecurity(frequency));
                if (ISecurityUtils.INSTANCE.moreRestrictive(old, mode)) {
                    validateAccess();
                }
            }
        }
    }

    public void addTrusted(String name) {
        if (level != null) {
            MinecraftServer server = level.getServer();
            if (server != null) {
                UserNameToIdResolver nameToIdCache = server.services().nameToIdCache();
                SecurityFrequency frequency = getFreq();
                if (frequency != null) {
                    Optional<NameAndId> gameProfile = nameToIdCache.get(name);
                    //noinspection OptionalIsPresent - Capturing lambda
                    if (gameProfile.isPresent()) {
                        NameAndId profile = gameProfile.get();
                        frequency.addTrusted(profile.id(), profile.name());
                    }
                }
            }
        }
    }

    @Nullable
    public SecurityFrequency getFreq() {
        return getFrequency(FrequencyTypes.SECURITY);
    }
}

package mekanism.common.lib.security;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import io.netty.buffer.ByteBuf;
import java.util.Collections;
import java.util.List;
import java.util.Optional;
import java.util.UUID;
import mekanism.api.SerializationConstants;
import mekanism.api.security.SecurityMode;
import mekanism.common.lib.collection.HashList;
import mekanism.common.lib.frequency.Frequency;
import mekanism.common.lib.frequency.FrequencyTypes;
import mekanism.common.network.PacketUtils;
import mekanism.common.util.MekanismUtils;
import net.minecraft.core.UUIDUtil;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import org.jspecify.annotations.Nullable;

public class SecurityFrequency extends Frequency {

    public static final String SECURITY = "Security";

    public static final Codec<SecurityFrequency> CODEC = RecordCodecBuilder.create(instance -> instance.group(
          UUIDUtil.CODEC.optionalFieldOf(SerializationConstants.OWNER_UUID).forGetter(freq -> Optional.ofNullable(freq.getOwner())),
          SecurityMode.CODEC.fieldOf(SerializationConstants.SECURITY_MODE).forGetter(SecurityFrequency::getSecurity),
          Codec.BOOL.fieldOf(SerializationConstants.OVERRIDE).forGetter(SecurityFrequency::isOverridden),
          UUIDUtil.CODEC.listOf().optionalFieldOf(SerializationConstants.TRUSTED).forGetter(freq -> freq.trusted.isEmpty() ? Optional.empty() : Optional.of(freq.trusted.elements()))
    ).apply(instance, (owner, securityMode, override, trustedCache) -> {
        SecurityFrequency frequency = new SecurityFrequency(owner.orElse(null), securityMode);
        frequency.override = override;
        for (UUID trusted : trustedCache.orElse(Collections.emptyList())) {
            frequency.addTrustedRaw(trusted, MekanismUtils.getLastKnownUsername(trusted));
        }
        return frequency;
    }));
    public static final StreamCodec<ByteBuf, SecurityFrequency> STREAM_CODEC = StreamCodec.composite(
          ByteBufCodecs.optional(UUIDUtil.STREAM_CODEC), freq -> Optional.ofNullable(freq.getOwner()),
          ByteBufCodecs.stringUtf8(PacketUtils.LAST_USERNAME_LENGTH), SecurityFrequency::getOwnerName,
          SecurityMode.STREAM_CODEC, SecurityFrequency::getSecurity,
          ByteBufCodecs.BOOL, SecurityFrequency::isOverridden,
          ByteBufCodecs.stringUtf8(PacketUtils.LAST_USERNAME_LENGTH).<HashList<String>>apply(buf -> ByteBufCodecs.collection(HashList::new, buf)), freq -> freq.trustedCache,
          (owner, ownerName, securityMode, override, trustedCache) -> {
              SecurityFrequency frequency = new SecurityFrequency(owner.orElse(null), ownerName, securityMode);
              frequency.override = override;
              frequency.trustedCache = trustedCache;
              return frequency;
          }
    );

    private boolean override = false;

    private final HashList<UUID> trusted = new HashList<>();
    private HashList<String> trustedCache = new HashList<>();
    private int trustedCacheHash;

    /// @param uuid Should only be null if we have incomplete data that we are loading
    public SecurityFrequency(@Nullable UUID uuid, SecurityMode securityMode) {
        super(FrequencyTypes.SECURITY, SECURITY, uuid, securityMode);
    }

    private SecurityFrequency(@Nullable UUID owner, String ownerName, SecurityMode securityMode) {
        super(FrequencyTypes.SECURITY, SECURITY, owner, ownerName, securityMode);
    }

    @Override
    public UUID getKey() {
        return getOwner();
    }

    @Override
    public int getSyncHash() {
        int code = super.getSyncHash();
        code = 31 * code + (override ? 1 : 0);
        //We skip including the security in the normal hashcode, but we do need to include it in the sync hashcode
        code = 31 * code + getSecurity().ordinal();
        code = 31 * code + trustedCacheHash;
        return code;
    }

    public void setOverridden(boolean override) {
        if (this.override != override) {
            this.override = override;
            this.dirty = true;
        }
    }

    @Override
    public FrequencyIdentity getIdentity() {
        return new FrequencyIdentity(getKey(), SecurityMode.PUBLIC, getOwner());
    }

    public boolean isOverridden() {
        return override;
    }

    public boolean isTrusted(UUID subject) {
        return trusted.contains(subject);
    }

    public List<String> getTrustedUsernameCache() {
        return trustedCache.elements();
    }

    public void addTrusted(UUID uuid, String name) {
        if (!trusted.contains(uuid)) {
            addTrustedRaw(uuid, name);
            this.dirty = true;
        }
    }

    private void addTrustedRaw(UUID uuid, String name) {
        trusted.add(uuid);
        trustedCache.add(name);
        trustedCacheHash = trustedCache.hashCode();
    }

    @Nullable
    public UUID removeTrusted(int index) {
        UUID uuid = null;
        if (index >= 0 && index < trusted.size()) {
            uuid = trusted.remove(index);
            this.dirty = true;
        }
        if (index >= 0 && index < trustedCache.size()) {
            trustedCache.remove(index);
            trustedCacheHash = trustedCache.hashCode();
        }
        return uuid;
    }
}

package mekanism.common.inventory.container;

import net.minecraft.world.entity.player.Player;

