package mekanism.common.lib.frequency;

import com.mojang.datafixers.util.Pair;
import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.function.Consumer;
import mekanism.api.SerializationConstants;
import mekanism.api.security.SecurityMode;
import mekanism.common.Mekanism;
import mekanism.common.content.qio.TickableFrequency;
import mekanism.common.lib.frequency.Frequency.FrequencyIdentity;
import mekanism.common.lib.security.SecurityFrequency;
import net.minecraft.core.UUIDUtil;
import net.minecraft.resources.Identifier;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.saveddata.SavedData;
import org.jspecify.annotations.Nullable;

/// Stores a map of Identity to Frequency (Data)
public class FrequencyLookup<FREQ extends Frequency> extends SavedData {

    public static final int MAX_FREQ_LENGTH = 16;

    private final Map<Object, FREQ> frequencies = new LinkedHashMap<>();

    @Nullable
    private final UUID ownerUUID;

    private final FrequencyType<FREQ> frequencyType;
    private final SecurityMode securityMode;

    public FrequencyLookup(FrequencyType<FREQ> frequencyType, @Nullable UUID uuid, SecurityMode securityMode) {
        this(frequencyType, uuid, securityMode, Collections.emptyList());
    }

    private FrequencyLookup(FrequencyType<FREQ> frequencyType, @Nullable UUID uuid, SecurityMode securityMode, List<FREQ> loadedFrequencies) {
        this.frequencyType = frequencyType;
        ownerUUID = uuid;
        this.securityMode = securityMode;
        for (FREQ loadedFrequency : loadedFrequencies) {
            frequencies.put(loadedFrequency.getKey(), loadedFrequency);
        }
    }

    @Nullable
    public UUID getOwnerUUID() {
        return ownerUUID;
    }

    public FrequencyType<FREQ> getFrequencyType() {
        return frequencyType;
    }

    public boolean remove(Object key, UUID ownerUUID) {
        FREQ freq = getFrequency(key);
        if (freq != null && freq.ownerMatches(ownerUUID)) {
            freq.onRemove();
            frequencies.remove(key);
            setDirty();
            return true;
        }
        return false;
    }

    public void deactivate(@Nullable Frequency freq, Level level, BlockEntity tile) {
        if (freq != null && freq.onDeactivate(level, tile)) {
            setDirty();
        }
    }

    public FREQ validateAndUpdate(Level level, BlockEntity tile, FREQ freq) {
        FREQ storedFreq = frequencies.get(freq.getKey());
        if (storedFreq == null) {
            freq.setValid(true);
            setDirty();
            frequencies.put(freq.getKey(), freq);
            storedFreq = freq;
        }
        if (storedFreq.update(level, tile)) {
            setDirty();
        }
        return storedFreq;
    }

    public Collection<FREQ> getFrequencies() {
        if (securityMode == SecurityMode.TRUSTED && ownerUUID != null) {
            //TODO: Try to come up with a better way of doing this that allows us to cache this
            FrequencyLookup<SecurityFrequency> securityLookup = FrequencyTypes.SECURITY.getLookup(null, SecurityMode.PUBLIC);
            if (securityLookup == null) {
                return Collections.emptyList();
            }
            List<FREQ> trustedFrequencies = new ArrayList<>(frequencies.values());
            for (FrequencyLookup<FREQ> trustedLookup : frequencyType.getController().getTrustedLookups()) {
                if (!ownerUUID.equals(trustedLookup.ownerUUID)) {
                    //Add any frequencies that the owner has access to because of being trusted by the other player
                    SecurityFrequency frequency = securityLookup.getFrequency(trustedLookup.ownerUUID);
                    if (frequency != null && frequency.isTrusted(ownerUUID)) {
                        trustedFrequencies.addAll(trustedLookup.frequencies.values());
                    }
                }
            }
            return trustedFrequencies;
        }
        return frequencies.values();
    }

    @Nullable
    public FREQ getFrequency(@Nullable Object key) {
        return key == null ? null : frequencies.get(key);
    }

    public FREQ getOrCreateFrequency(FrequencyIdentity identity, @Nullable UUID ownerUUID) {
        FREQ freq = frequencies.get(identity.key());
        if (freq == null) {
            freq = frequencyType.create(identity.key(), ownerUUID, identity.securityMode());
            frequencies.put(identity.key(), freq);
            setDirty();
        }
        return freq;
    }

    public void addFrequency(FREQ freq) {
        frequencies.put(freq.getKey(), freq);
        setDirty();
    }

    public FrequencyType<FREQ> getType() {
        return frequencyType;
    }

    public void tickSelf(boolean tickingNormally) {
        boolean dirty = false;
        for (FREQ freq : frequencies.values()) {
            dirty |= ((TickableFrequency) freq).tick(tickingNormally);
        }
        if (dirty) {
            setDirty();
        }
    }

    public static Identifier getId(@Nullable UUID ownerUUID, SecurityMode securityMode, FrequencyType<?> frequencyType) {
        StringBuilder path = new StringBuilder("frequency/");
        path.append(frequencyType.getName()).append("/");
        if (ownerUUID != null) {
            path.append(ownerUUID.toString().toLowerCase(Locale.ROOT)).append("/");
        }
        path.append(securityMode.getSerializedName());
        return Mekanism.rl(path.toString());
    }

    private static final Consumer<String> frequencyError = err -> Mekanism.logger.error("Failed to load some frequencies: {}", err);

    public static <FREQ extends Frequency> Codec<Pair<Optional<UUID>, List<FREQ>>> baseCodec(FrequencyType<FREQ> frequencyType) {
        return RecordCodecBuilder.create(instance -> instance.group(
              UUIDUtil.CODEC.optionalFieldOf(SerializationConstants.OWNER_UUID).forGetter(Pair::getFirst),
              frequencyType.codec().listOf().promotePartial(frequencyError).fieldOf(SerializationConstants.FREQUENCY_LIST).forGetter(Pair::getSecond)
        ).apply(instance, Pair::new));
    }

    public static <FREQ extends Frequency> Codec<FrequencyLookup<FREQ>> codec(FrequencyType<FREQ> frequencyType, Codec<Pair<Optional<UUID>, List<FREQ>>> baseCodec, SecurityMode securityMode) {
        return baseCodec.xmap(
              pair -> new FrequencyLookup<>(frequencyType, pair.getFirst().orElse(null), securityMode, pair.getSecond()),
              lookup -> Pair.of(Optional.ofNullable(lookup.getOwnerUUID()), new ArrayList<>(lookup.frequencies.values()))
        );
    }
}

package mekanism.common.lib.frequency;

import com.mojang.serialization.Codec;
import java.util.ArrayList;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import mekanism.api.security.SecurityMode;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.level.saveddata.SavedDataType;
import net.minecraft.world.level.storage.SavedDataStorage;
import org.jspecify.annotations.Nullable;

public class FrequencyControllerManager {

    static final List<FrequencyLookup<?>> tickableLookups = new ArrayList<>();
    @Nullable
    private static SavedDataStorage dataStorage = null;
    private static final Map<FrequencyType<?>, FrequencyController<?>> controllers = new IdentityHashMap<>(FrequencyTypes.allRegistered().size());

    public static void serverLoad(MinecraftServer server) {
        dataStorage = server.getDataStorage();
        for (FrequencyType<?> frequencyType : FrequencyTypes.allRegistered()) {
            controllers.put(frequencyType, FrequencyController.create(frequencyType));
        }
    }

    public static void reset() {
        dataStorage = null;
        tickableLookups.clear();
        controllers.clear();
    }

    @SuppressWarnings("unchecked")
    public static <FREQ extends Frequency> FrequencyController<FREQ> getController(FrequencyType<FREQ> frequencyType) {
        return (FrequencyController<FREQ>) controllers.get(frequencyType);
    }

    protected static <FREQ extends Frequency> FrequencyLookup<FREQ> createLookup(FrequencyType<FREQ> frequencyType, @Nullable UUID uuid, SecurityMode securityMode, Codec<FrequencyLookup<FREQ>> codec) {
        FrequencyLookup<FREQ> lookup;
        if (dataStorage == null) {
            //assume client - TODO - 26.3 - does this even get called on the client? seems not
            lookup = new FrequencyLookup<>(frequencyType, uuid, securityMode);
        } else {
            SavedDataType<FrequencyLookup<FREQ>> dataType = new SavedDataType<>(
                  FrequencyLookup.getId(uuid, securityMode, frequencyType),
                  () -> new FrequencyLookup<>(frequencyType, uuid, securityMode),
                codec
            );
            lookup = dataStorage.computeIfAbsent(dataType);
        }
        registerTickable(lookup);
        return lookup;
    }

    public static void registerTickable(FrequencyLookup<?> lookup) {
        if (lookup.getFrequencyType().needsTick()) {
            tickableLookups.add(lookup);
        }
    }

    public static void tick(boolean tickingNormally) {
        for (FrequencyLookup<?> lookup : tickableLookups) {
            lookup.tickSelf(tickingNormally);
        }
    }
}

private <FREQ extends Frequency> void updateFrequency(FrequencyType<FREQ> type, FrequencyData frequencyData, Level level) {
    if (frequencyData.selectedFrequency != null) {
        if (frequencyData.selectedFrequency.isValid()) {
            boolean unsetFrequency = frequencyData.selectedFrequency.isRemoved();
            //Note: Security frequencies can only be public, and security means something different on them. So even if it is set as trusted, we don't need to check this
            if (!unsetFrequency && type != FrequencyTypes.SECURITY && frequencyData.selectedFrequency.getSecurity() == SecurityMode.TRUSTED) {
                //If we aren't unsetting the frequency, check if it is a trusted frequency that we no longer have access to
                UUID ownerUUID = tile.getOwnerUUID();
                if (ownerUUID != null && !frequencyData.selectedFrequency.ownerMatches(ownerUUID)) {
                    SecurityFrequency security = FrequencyTypes.SECURITY.getFrequency(null, SecurityMode.PUBLIC, frequencyData.selectedFrequency.getOwner());
                    unsetFrequency = security != null && !security.isTrusted(ownerUUID);
                }
            }
            if (unsetFrequency) {
                FrequencyLookup<FREQ> manager = type.getFrequencyLookup((FREQ) frequencyData.selectedFrequency);
                if (manager != null) {
                    manager.deactivate(frequencyData.selectedFrequency, level, tile);
                }
                frequencyData.clearFrequency();
                setNeedsNotify(frequencyData);
            }
            //Note: We don't need to update the frequency for this block as in cases when it isn't invalid we do it immediately
        } else {
            FREQ frequency = (FREQ) frequencyData.selectedFrequency;
            FrequencyLookup<FREQ> manager = type.getFrequencyLookup(frequency);
            if (manager == null) {
                frequencyData.clearFrequency();
            } else {
                frequencyData.setFrequency(manager.validateAndUpdate(level, tile, frequency));
            }
            setNeedsNotify(frequencyData);
        }
    }
}

private void setNeedsNotify(FrequencyData data) {
    if (data.notifyNeighbors) {
        needsNotify = true;
    }
    needsSave = true;
}

private <FREQ extends Frequency> void deactivate(Level level, FrequencyType<FREQ> type, FrequencyData frequencyData) {
    if (frequencyData.selectedFrequency != null) {
        FrequencyLookup<FREQ> manager = type.getFrequencyLookup((FREQ) frequencyData.selectedFrequency);
        if (manager != null) {
            manager.deactivate(frequencyData.selectedFrequency, level, tile);
        }
    }
}

package mekanism.common.lib.security;

import it.unimi.dsi.fastutil.objects.ObjectOpenHashSet;
import java.util.Set;
import java.util.UUID;
import mekanism.api.security.IBlockSecurityUtils;
import mekanism.api.security.IOwnerObject;
import mekanism.api.security.ISecurityObject;
import mekanism.api.security.ISecurityUtils;
import mekanism.api.security.SecurityMode;
import mekanism.common.capabilities.Capabilities;
import net.minecraft.core.BlockPos;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.neoforged.neoforge.capabilities.BlockCapability;
import org.jspecify.annotations.Nullable;

/// @apiNote Do not instantiate this class directly as it will be done via the service loader. Instead, access instances of this via [IBlockSecurityUtils#INSTANCE]
public class BlockSecurityUtils implements IBlockSecurityUtils {

    private static final BlockCapability<IOwnerObject, @Nullable Void> OWNER_CAPABILITY = BlockCapability.createVoid(Capabilities.OWNER_OBJECT_NAME, IOwnerObject.class);
    private static final BlockCapability<ISecurityObject, @Nullable Void> SECURITY_CAPABILITY = BlockCapability.createVoid(Capabilities.SECURITY_OBJECT_NAME, ISecurityObject.class);

    public static BlockSecurityUtils get() {
        return (BlockSecurityUtils) INSTANCE;
    }

    @Override
    public BlockCapability<IOwnerObject, @Nullable Void> ownerCapability() {
        return OWNER_CAPABILITY;
    }

    @Override
    public BlockCapability<ISecurityObject, @Nullable Void> securityCapability() {
        return SECURITY_CAPABILITY;
    }

    @Override
    public boolean canAccess(Player player, Level level, BlockPos pos, @Nullable BlockState state, @Nullable BlockEntity blockEntity) {
        CachingCapabilityLookup lookup = new CachingCapabilityLookup(level, pos, state, blockEntity);
        return ISecurityUtils.INSTANCE.canAccess(player, lookup, CachingCapabilityLookup::securityCapability, CachingCapabilityLookup::ownerCapability);
    }

    @Override
    public boolean canAccess(@Nullable UUID player, Level level, BlockPos pos, @Nullable BlockState state, @Nullable BlockEntity blockEntity) {
        CachingCapabilityLookup lookup = new CachingCapabilityLookup(level, pos, state, blockEntity);
        return ISecurityUtils.INSTANCE.canAccess(player, lookup, CachingCapabilityLookup::securityCapability, CachingCapabilityLookup::ownerCapability, level.isClientSide());
    }

    @Override
    public SecurityMode getSecurityMode(Level level, BlockPos pos, @Nullable BlockState state, @Nullable BlockEntity blockEntity) {
        CachingCapabilityLookup lookup = new CachingCapabilityLookup(level, pos, state, blockEntity);
        return ISecurityUtils.INSTANCE.getSecurityMode(lookup, CachingCapabilityLookup::securityCapability, CachingCapabilityLookup::ownerCapability, level.isClientSide());
    }

    public void securityChanged(Set<Player> playersUsing, Level level, BlockPos pos, @Nullable BlockEntity target, SecurityMode old, SecurityMode mode) {
        //If the mode changed and the new security mode is more restrictive than the old one
        // and there are players using the security object
        if (!playersUsing.isEmpty() && ISecurityUtils.INSTANCE.moreRestrictive(old, mode)) {
            //then double check that all the players are actually supposed to be able to access the GUI
            //Note: We directly store and then query our caching capability lookup so that we don't have to re-look up
            // the capabilities of the block for each player
            CachingCapabilityLookup lookup = new CachingCapabilityLookup(level, pos, null, target);
            for (Player player : new ObjectOpenHashSet<>(playersUsing)) {
                if (!ISecurityUtils.INSTANCE.canAccess(player, lookup, CachingCapabilityLookup::securityCapability, CachingCapabilityLookup::ownerCapability)) {
                    //and if they can't then boot them out
                    player.closeContainer();
                }
            }
        }
    }

    /// Used to allow caching the block state and block entity lookup between security capability and owner capability lookup. That way if the block queried does not
    /// expose a security capability at the given position we don't have to do more world lookups when querying if the block exposes an owner capability.
    ///
    /// @implNote As this caches the security and owner objects, this is not suitable for persisting between calls.
    private static class CachingCapabilityLookup {

        private record BlockTarget(BlockState state, @Nullable BlockEntity blockEntity) {
        }

        private final Level level;
        private final BlockPos pos;
        @Nullable
        private final BlockState knownState;
        @Nullable
        private final BlockEntity knownBlockEntity;
        @Nullable
        private BlockTarget target;
        @Nullable
        private ISecurityObject securityObject;
        @Nullable
        private IOwnerObject ownerObject;

        CachingCapabilityLookup(Level level, BlockPos pos, @Nullable BlockState knownState, @Nullable BlockEntity knownBlockEntity) {
            this.level = level;
            this.pos = pos;
            this.knownState = knownState;
            this.knownBlockEntity = knownBlockEntity;
        }

        private BlockTarget getTarget() {
            if (target == null) {
                // Get block state and block entity if they were not provided
                BlockState state = knownState;
                BlockEntity blockEntity = knownBlockEntity;
                //Note: We use the same logic as BlockCapability uses for minimizing level queries here
                if (blockEntity == null) {
                    if (state == null) {
                        state = level.getBlockState(pos);
                    }
                    if (state.hasBlockEntity()) {
                        //Note: We intentionally look up directly rather than using WorldUtils that validates the position is loaded
                        // it is the responsibility of the caller to check if the position they are querying is loaded
                        blockEntity = level.getBlockEntity(pos);
                    }
                } else if (state == null) {
                    state = blockEntity.getBlockState();
                }
                target = new BlockTarget(state, blockEntity);
            }
            return target;
        }

        @Nullable
        ISecurityObject securityCapability() {
            if (securityObject == null) {
                BlockTarget blockTarget = getTarget();
                securityObject = INSTANCE.securityCapability(level, pos, blockTarget.state(), blockTarget.blockEntity());
            }
            return securityObject;
        }

        @Nullable
        IOwnerObject ownerCapability() {
            if (ownerObject == null) {
                BlockTarget blockTarget = getTarget();
                ownerObject = INSTANCE.ownerCapability(level, pos, blockTarget.state(), blockTarget.blockEntity());
            }
            return ownerObject;
        }
    }
}

